use vstd::prelude::*;

verus! {

fn swap_first_and_last(a: &mut Vec<i32>)
    requires
        old(a).len() > 0,
    ensures
        a.len() == old(a).len(),
        // first becomes old last, last becomes old first
        a[0] == old(a)[old(a).len() - 1],
        a[a.len() - 1] == old(a)[0],
        // middle elements unchanged
        forall|i: int|
            0 < i && i < a.len() - 1 ==> a[i] == old(a)[i],
{
    let n: usize = a.len();
    assert(n > 0);

    if n == 1 {
        // Swapping first/last is a no-op, but we still satisfy the postcondition.
        return;
    }

    // Snapshot the values to be swapped.
    let first: i32 = a[0];
    let last: i32 = a[n - 1];

    // Perform the swap in place.
    a.set(0, last);
    a.set(n - 1, first);

    // (Optional) small sanity facts for the verifier
    assert(a.len() == n);
    assert(a[0] == old(a)[old(a).len() - 1]);
    assert(a[n - 1] == old(a)[0]);
    assert(forall|i: int| 0 < i && i < n - 1 ==> a[i] == old(a)[i]);
}

} // verus!

